--
-- mod-raid-clear-tracker :: world database catalogue
--
-- AUTO-GENERATED by apps/tools/generate_progression_sql.py from progression/*.json.
-- Do not edit the seed rows by hand here; edit the JSON and regenerate, OR edit the
-- rows directly in your world database (INSERT IGNORE means your rows are preserved).
--
-- content_type   : 0 = dungeon, 1 = raid, 2 = world boss
-- expansion      : 0 = classic, 1 = tbc, 2 = wotlk
-- difficulty     : flat scale  0=5N 1=5HC 2=10N 3=20N 4=25N 5=40N 6=10HC 7=25HC (world boss = 0)
-- dungeon_version: 'base' when a map hosts a single instance; a distinct label
--                  (e.g. 'lbrs'/'ubrs', 'classic'/'wotlk') when several instances
--                  share one map id, so a run can be pinned to the right one.
--

CREATE TABLE IF NOT EXISTS `raid_tracker_instance` (
  `id`              INT UNSIGNED      NOT NULL,
  `content_type`    TINYINT UNSIGNED  NOT NULL,
  `expansion`       TINYINT UNSIGNED  NOT NULL DEFAULT 0,
  `map_id`          SMALLINT UNSIGNED NOT NULL,
  `dungeon_version` VARCHAR(32)       NOT NULL DEFAULT 'base',
  `instance_key`    VARCHAR(64)       NOT NULL DEFAULT '',
  `name`            VARCHAR(128)      NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_map` (`map_id`),
  KEY `idx_content` (`content_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Instances/world bosses tracked by mod-raid-clear-tracker';

CREATE TABLE IF NOT EXISTS `raid_tracker_instance_difficulty` (
  `instance_id` INT UNSIGNED     NOT NULL,
  `difficulty`  TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (`instance_id`, `difficulty`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Flat-scale difficulties an instance is tracked under';

CREATE TABLE IF NOT EXISTS `raid_tracker_boss` (
  `id`          INT UNSIGNED      NOT NULL,
  `instance_id` INT UNSIGNED      NOT NULL,
  `name`        VARCHAR(128)      NOT NULL DEFAULT '',
  `order_index` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `is_final`    TINYINT UNSIGNED  NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_instance` (`instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bosses per instance; is_final marks the encounter that ends a clear';

CREATE TABLE IF NOT EXISTS `raid_tracker_boss_npc` (
  `boss_id`   INT UNSIGNED NOT NULL,
  `npc_entry` INT UNSIGNED NOT NULL,
  PRIMARY KEY (`npc_entry`, `boss_id`),
  KEY `idx_boss` (`boss_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='creature_template.entry -> boss lookup (an entry may belong to several bosses)';




